//---------------------------------------------------------------------------//
// Unit test for tools/num2s
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/num2s"

#include <gtest/gtest.h>

#include <limits>
#include <string>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(Num2s, UnsignedShort)
{
  std::string s;
  EXPECT_TRUE(num2s((unsigned short)42, s));
  EXPECT_EQ(s, "42");
}

TEST(Num2s, Short)
{
  std::string s;
  EXPECT_TRUE(num2s((short)-42, s));
  EXPECT_EQ(s, "-42");
}

//---------------------------------------------------------------------------//
TEST(Num2s, UnsignedInt)
{
  std::string s;
  EXPECT_TRUE(num2s((unsigned int)123456, s));
  EXPECT_EQ(s, "123456");
}

TEST(Num2s, Int)
{
  std::string s;
  EXPECT_TRUE(num2s(-123456, s));
  EXPECT_EQ(s, "-123456");
}

//---------------------------------------------------------------------------//
TEST(Num2s, UInt64)
{
  auto max = std::numeric_limits<uint64>::max();
  std::string s;
  EXPECT_TRUE(num2s(max, s));
  EXPECT_EQ(s, std::to_string(max));
}

TEST(Num2s, Int64)
{
  auto min = std::numeric_limits<int64>::min();
  std::string s;
  EXPECT_TRUE(num2s(min, s));
  EXPECT_EQ(s, std::to_string(min));
}

//---------------------------------------------------------------------------//
TEST(Num2s, Float)
{
  std::string s;
  EXPECT_TRUE(num2s(1.23f, s));
  // "%g" formatting may output "1.23"
  EXPECT_EQ(s, "1.23");
}

TEST(Num2s, Double)
{
  std::string s;
  EXPECT_TRUE(num2s(123456.0, s));
  EXPECT_EQ(s, "123456");
}

//---------------------------------------------------------------------------//
TEST(Num2s, StringPassthrough)
{
  std::string s;
  EXPECT_TRUE(num2s(std::string("hello"), s));
  EXPECT_EQ(s, "hello");
}

//---------------------------------------------------------------------------//
TEST(Nums2s, VectorInts)
{
  std::vector<int> vals = {1, 2, 3};
  std::string s;
  EXPECT_TRUE(nums2s(vals, s, ","));
  EXPECT_EQ(s, "1,2,3");
}

TEST(Nums2s, EmptyVector)
{
  std::vector<int> vals;
  std::string s;
  EXPECT_TRUE(nums2s(vals, s));
  EXPECT_EQ(s, "");
}

//---------------------------------------------------------------------------//
TEST(Numas, AppendNumeric)
{
  std::string s = "prefix";
  EXPECT_TRUE(numas(99, s));
  EXPECT_EQ(s, "prefix99");
}

TEST(Numas, AppendFloat)
{
  std::string s = "value=";
  EXPECT_TRUE(numas(3.14f, s));
  EXPECT_EQ(s, "value=3.14");
}

//---------------------------------------------------------------------------//
TEST(NumOut, QuotedInt)
{
  EXPECT_EQ(num_out(42), "\"42\"");
}

TEST(NumOut, QuotedFloat)
{
  EXPECT_EQ(num_out(2.5f), "\"2.5\"");
}

TEST(NumOut, QuotedString)
{
  EXPECT_EQ(num_out<std::string>("abc"), "\"abc\"");
}

//---------------------------------------------------------------------------//
}  // namespace tools
